/// Runs finite real-SQL controls against the existing supplied-fact store.
module UsageBoundaryExperiment

open System
open System.IO
open System.Globalization
open System.Text.Json
open System.Threading
open System.Threading.Tasks
open Grace.Shared
open Grace.Types.Usage
open Grace.Operations.Data
open Microsoft.Data.SqlClient
open NodaTime

/// Requires an explicit disposable fixture environment value.
let required name =
    let value = Environment.GetEnvironmentVariable name
    if String.IsNullOrWhiteSpace value then failwith $"Missing {name}."
    value

/// Creates fresh connections without retaining pooled caller state between controls.
let connectionString = required "OPS1054_SQL"
/// Locates captured input and output files outside the repository.
let artifact = required "OPS1054_ARTIFACT"
/// Serializes exact current Grace contracts with the compiled shared options.
let serialize value = JsonSerializer.Serialize(value, Constants.JsonSerializerOptions)
/// Renders evidence arrays without dropping zero or empty values.
let evidenceJson value = JsonSerializer.Serialize(value, JsonSerializerOptions(WriteIndented = true))
/// Throws on a finite control mismatch.
let equal label expected actual = if expected <> actual then failwith $"{label}: expected {expected}; actual {actual}"
/// Provides deterministic GUIDs for the finite fixture.
let id number = Guid.Parse(sprintf "10540000-0000-0000-0000-%012d" number)
/// Constructs supplied values, deliberately unrelated to live source measurements.
let fact number pool quantity =
    UsageFact.RepositoryStorageBytesMinute(id number, $"ops1054-{number}", id 1000, id 2000, id 3000, pool, quantity, Instant.FromUtc(2026,9,7,12,34,56))
/// Saves a fixture once and reloads its exact bytes for every attempt and retry.
let captured name value =
    let path = Path.Combine(artifact, name + ".input.json")
    let json = serialize value
    if File.Exists path then equal (name + " captured input") json (File.ReadAllText path)
    else File.WriteAllText(path, json)
    JsonSerializer.Deserialize<UsageFact>(File.ReadAllText path, Constants.JsonSerializerOptions)

/// Wraps public interfaces while all writes and commit/rollback use the compiled SQL scope.
let scope boundary =
    let real = SqlOperationsUsageTransactionScope(connectionString) :> IOperationsUsageTransactionScope
    { new IOperationsUsageTransactionScope with
        /// Injects only at named effect boundaries; after-commit discards a successful result.
        member _.ExecuteAsync(operation, token) =
            task {
                let! result = real.ExecuteAsync((fun transaction ct ->
                    task {
                        let wrapped =
                            { new IOperationsUsageTransaction with
                                /// Runs the real raw insert unless the before-write control is selected.
                                member _.TryInsertRawUsageFactAsync(raw, innerToken) =
                                    task {
                                        if boundary = "before-write" then failwith "injected:before-write"
                                        let! accepted = transaction.TryInsertRawUsageFactAsync(raw, innerToken)
                                        if boundary = "after-raw" then failwith "injected:after-raw"
                                        return accepted
                                    }
                                /// Runs the real aggregate update before the transaction-level precommit injection.
                                member _.AddToUsageAggregateMinuteAsync(aggregate, innerToken) = transaction.AddToUsageAggregateMinuteAsync(aggregate, innerToken) }
                        let! result = operation wrapped ct
                        if boundary = "before-commit" then failwith "injected:before-commit"
                        return result
                    }), token)
                if boundary = "after-commit" then failwith "injected:after-commit"
                return result
            } }

/// Creates a fresh store and scope for every call, including retry after injected failure.
let submit boundary value token =
    task {
        let store = OperationsUsageStore(scope boundary)
        try
            let! result = store.StoreUsageFactAsync(value, token)
            return match result with Ok result -> string result.Status | Error errors -> "Invalid: " + String.concat "; " errors
        with
        | :? OperationCanceledException -> return "Cancelled"
        | ex when ex.Message.StartsWith("injected:", StringComparison.Ordinal) -> return ex.Message
    }

/// Formats stable durable fields independently from the store's result object.
let cell (value: obj) =
    match value with
    | :? DateTime as dt -> DateTime.SpecifyKind(dt, DateTimeKind.Utc).ToString("O", CultureInfo.InvariantCulture)
    | _ -> Convert.ToString(value, CultureInfo.InvariantCulture)

/// Queries real committed rows through a new connection, including all immutable raw fields.
let rows table pool =
    use connection = new SqlConnection(connectionString)
    connection.Open()
    use command = connection.CreateCommand()
    let columns, ordering =
        if table = "RawUsageFact" then "UsageFactId, CorrelationId, FactKind, OwnerId, OrganizationId, RepositoryId, StoragePoolId, Quantity, ObservedAtUtc", "UsageFactId"
        else "FactKind, OwnerId, OrganizationId, RepositoryId, StoragePoolId, BucketStartUtc, Quantity", "OwnerId, OrganizationId, RepositoryId, StoragePoolId, BucketStartUtc"
    command.CommandText <- $"SELECT {columns} FROM ops.{table} WHERE StoragePoolId IN (@pool, @otherPool) ORDER BY {ordering};"
    command.Parameters.AddWithValue("@pool", pool) |> ignore
    command.Parameters.AddWithValue("@otherPool", pool + "-changed") |> ignore
    use reader = command.ExecuteReader()
    let result = ResizeArray<string array>()
    while reader.Read() do
        result.Add(Array.init reader.FieldCount (fun index -> cell (reader.GetValue index)))
    result.ToArray()

/// Computes expected raw fields from explicit fixture values, without reading the store result or plan.
let expectedRaw (value: UsageFact) =
    [| string value.UsageFactId; value.CorrelationId; string (int value.FactKind); string value.Scope.OwnerId; string value.Scope.OrganizationId; string value.Scope.RepositoryId; value.Resource.StoragePoolId; string value.Quantity; value.ObservedAt.ToDateTimeUtc().ToString("O", CultureInfo.InvariantCulture) |]
/// Computes the expected aggregate key and explicitly supplied total.
let expectedAggregate (value: UsageFact) total =
    [| string (int value.FactKind); string value.Scope.OwnerId; string value.Scope.OrganizationId; string value.Scope.RepositoryId; value.Resource.StoragePoolId; value.ObservedAt.ToDateTimeUtc().ToString("O", CultureInfo.InvariantCulture); string total |]
/// Retains the finite checked ledger for the repository evidence bundle.
let ledger = ResizeArray<obj>()
/// Checks both independent SQL queries against exact expected durable rows.
let check name statuses pool expectedFacts aggregateRows =
    let expectedRawRows = expectedFacts |> Array.map expectedRaw |> Array.sortBy (fun row -> row[0])
    let raw = rows "RawUsageFact" pool
    let aggregates = rows "UsageAggregateMinute" pool
    equal (name + " raw") (evidenceJson expectedRawRows) (evidenceJson raw)
    equal (name + " aggregates") (evidenceJson aggregateRows) (evidenceJson aggregates)
    ledger.Add(box {| Name = name; Statuses = statuses; ExpectedRaw = expectedRawRows; Raw = raw; ExpectedAggregates = aggregateRows; Aggregates = aggregates |})
    printfn "PASS %s: %s" name (String.concat ", " statuses)

/// Executes each finite control once against a new, initially empty fixture database.
let run () = task {
    let builder = SqlConnectionStringBuilder(connectionString)
    if not (builder.InitialCatalog.StartsWith("GraceOps1054_", StringComparison.Ordinal)) then failwith "Fixture database must start GraceOps1054_."
    if builder.DataSource <> "127.0.0.1,14339" then failwith "Fixture endpoint must be 127.0.0.1,14339."
    let schema = OperationsUsageSchema(connectionString, OperationsUsageSchemaBootstrapMode.CreateDatabaseIfMissing)
    do! schema.EnsureCreatedAsync(CancellationToken.None)
    use connection = new SqlConnection(connectionString)
    do! connection.OpenAsync()
    use count = connection.CreateCommand()
    count.CommandText <- "SELECT (SELECT COUNT(*) FROM ops.RawUsageFact) + (SELECT COUNT(*) FROM ops.UsageAggregateMinute);"
    equal "empty fixture" 0 (unbox<int> (count.ExecuteScalar()))
    use version = connection.CreateCommand()
    version.CommandText <- "SELECT @@VERSION;"
    File.WriteAllText(Path.Combine(artifact, "sql-version.txt"), string (version.ExecuteScalar()))

    let original = fact 1 "repeat" 17L
    let! first = submit "" (captured "original" original) CancellationToken.None
    equal "accept status" "Accepted" first
    check "01-positive" [|first|] "repeat" [|original|] [|expectedAggregate original 17L|]
    let! repeat = submit "" (captured "original" original) CancellationToken.None
    equal "fresh retry" "AlreadyProcessed" repeat
    check "02-identical-fresh-objects" [|repeat|] "repeat" [|original|] [|expectedAggregate original 17L|]
    let distinct = { original with UsageFactId = id 2; CorrelationId = "ops1054-2" }
    let! added = submit "" (captured "distinct" distinct) CancellationToken.None
    equal "distinct accepted" "Accepted" added
    check "03-distinct-id-adds" [|added|] "repeat" [|original; distinct|] [|expectedAggregate original 34L|]
    let changes = [| "quantity", {original with Quantity = 99L}; "owner", {original with Scope = {original.Scope with OwnerId = id 4000}}; "organization", {original with Scope = {original.Scope with OrganizationId = id 5000}}; "repository", {original with Scope = {original.Scope with RepositoryId = id 6000}}; "pool", {original with Resource = {StoragePoolId = "repeat-changed"}} |]
    let mutable index = 0
    while index < changes.Length do
        let label, changed = changes[index]
        let! result = submit "" (captured ("conflict-" + label) changed) CancellationToken.None
        equal (label + " conflict status") "AlreadyProcessed" result
        check ("04-conflict-" + label) [|result|] "repeat" [|original; distinct|] [|expectedAggregate original 34L|]
        index <- index + 1
    let invalids = [| "zero", {fact 10 "invalid" 1L with Quantity = 0L}, "Invalid: Quantity must be greater than zero."; "kind", {fact 11 "invalid" 1L with FactKind = enum<UsageFactKind> 99}, "Invalid: FactKind '99' is not supported."; "seconds", {fact 12 "invalid" 1L with ObservedAt = Instant.FromUtc(2026,9,7,12,34,56)}, "Invalid: ObservedAt must be normalized to a UTC minute boundary." |]
    index <- 0
    while index < invalids.Length do
        let label, value, expected = invalids[index]
        let loaded = captured label value
        let! result = submit "" loaded CancellationToken.None
        equal (label + " validation") expected result
        match UsageFactPersistencePlan.tryCreate loaded with Ok _ -> failwith "Invalid plan accepted." | Error _ -> ()
        check ("05-invalid-" + label) [|result|] "invalid" [||] [||]
        index <- index + 1
    let plan = UsageFactPersistencePlan.tryCreate original |> Result.defaultWith (String.concat "; " >> failwith)
    equal "constructor normalized" (Instant.FromUtc(2026,9,7,12,34,0)) original.ObservedAt
    equal "plan timestamp" original.ObservedAt plan.RawFact.ObservedAt
    File.WriteAllText(Path.Combine(artifact, "plan.json"), serialize plan)
    let boundaries = [| "before-write"; "after-raw"; "before-commit"; "after-commit" |]
    index <- 0
    while index < boundaries.Length do
        let boundary = boundaries[index]
        let value = fact (20 + index) boundary 23L
        let! failed = submit boundary (captured boundary value) CancellationToken.None
        equal (boundary + " failure") ("injected:" + boundary) failed
        let committed = boundary = "after-commit"
        check ("06-" + boundary + "-residue") [|failed|] boundary (if committed then [|value|] else [||]) (if committed then [|expectedAggregate value 23L|] else [||])
        SqlConnection.ClearAllPools()
        let! retry = submit "" (captured boundary value) CancellationToken.None
        equal (boundary + " restart") (if committed then "AlreadyProcessed" else "Accepted") retry
        check ("06-" + boundary + "-restart") [|retry|] boundary [|value|] [|expectedAggregate value 23L|]
        index <- index + 1
    let concurrent = fact 30 "concurrent" 31L
    let start = TaskCompletionSource<unit>(TaskCreationOptions.RunContinuationsAsynchronously)
    use ready = new CountdownEvent(2)
    /// Waits at the shared deterministic gate before constructing independent store calls.
    let gated () = task {
        let value = captured "concurrent" concurrent
        ready.Signal() |> ignore
        do! start.Task
        return! submit "" value CancellationToken.None
    }
    let a = gated ()
    let b = gated ()
    if not (ready.Wait(TimeSpan.FromSeconds 10.0)) then failwith "Concurrent callers not ready."
    start.SetResult()
    let! results = Task.WhenAll(a,b).WaitAsync(TimeSpan.FromSeconds 30.0)
    equal "concurrent statuses" [|"Accepted"; "AlreadyProcessed"|] (Array.sort results)
    check "07-concurrent-gated" (Array.sort results) "concurrent" [|concurrent|] [|expectedAggregate concurrent 31L|]
    use cancelled = new CancellationTokenSource()
    cancelled.Cancel()
    let! cancelledResult = submit "" (captured "cancelled" (fact 40 "cancelled" 37L)) cancelled.Token
    equal "precancelled" "Cancelled" cancelledResult
    check "08-pre-cancelled" [|cancelledResult|] "cancelled" [||] [||]
    File.WriteAllText(Path.Combine(artifact,"ledger.json"), evidenceJson (ledger.ToArray()))
    printfn "CONTROLS %d" ledger.Count
}

run().GetAwaiter().GetResult()

#Requires -Version 7.6
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Evidence,
    [Parameter(Mandatory)][string]$RepoRoot,
    [Parameter(Mandatory)][string]$OutputDirectory
)
$ErrorActionPreference = 'Stop'
$bundle = Get-Content -LiteralPath $Evidence -Raw | ConvertFrom-Json -Depth 100
if ([string]::IsNullOrWhiteSpace($env:OPS1054_SQL)) { throw 'Set OPS1054_SQL to the dedicated local fixture connection string with a fresh GraceOps1054_ database.' }
if (Test-Path -LiteralPath $OutputDirectory) { throw 'OutputDirectory must be a new external directory; no existing files are replaced.' }
$destination = [IO.Path]::GetFullPath($OutputDirectory)
$repository = (Resolve-Path -LiteralPath $RepoRoot).Path
if ($destination.StartsWith($repository + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { throw 'Use an output directory outside the repository.' }
foreach ($source in $bundle.sourceHashes) {
    $actual = (Get-FileHash -LiteralPath (Join-Path $repository $source.path) -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $source.sha256) { throw "Pinned source mismatch: $($source.path)" }
}
New-Item -ItemType Directory -Path $destination | Out-Null
foreach ($file in $bundle.executionFiles) {
    if ([IO.Path]::GetFileName($file.name) -ne $file.name) { throw 'Embedded files must have simple file names.' }
    $path = Join-Path $destination $file.name
    [IO.File]::WriteAllText($path, $file.text, [Text.UTF8Encoding]::new($false))
    if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256) { throw "Embedded hash mismatch: $($file.name)" }
}
Push-Location $repository
try {
    dotnet build ./src/Grace.Operations.Data/Grace.Operations.Data.fsproj -c Release -v minimal *> (Join-Path $destination 'production-build.log')
    $buildExit = $LASTEXITCODE
    if ($buildExit -ne 0) { throw "Production build failed: $buildExit" }
    dotnet build (Join-Path $destination 'Experiment.fsproj') -c Release "-p:GraceRoot=$repository" -p:BuildProjectReferences=false -v minimal *> (Join-Path $destination 'harness-build.log')
    $harnessExit = $LASTEXITCODE
    if ($harnessExit -ne 0) { throw "Harness build failed: $harnessExit" }
    $env:OPS1054_ARTIFACT = $destination
    dotnet (Join-Path $destination 'bin/Release/net10.0/Experiment.dll') *> (Join-Path $destination 'run.log')
    $runExit = $LASTEXITCODE
    if ($runExit -ne 0) { throw "Experiment failed: $runExit" }
    $actualLedger = (Get-FileHash -LiteralPath (Join-Path $destination 'ledger.json') -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actualLedger -ne $bundle.expectedLedgerSha256) { throw 'Replay ledger differs from the captured expected rows/statuses.' }
    $binaryHashes = @(Get-ChildItem -LiteralPath (Join-Path $destination 'bin/Release/net10.0') -Filter '*.dll' -File | Sort-Object Name | ForEach-Object {
        [ordered]@{ name = $_.Name; sha256 = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant() }
    })
    $binaryHashes | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $destination 'binary-hashes.json') -Encoding utf8NoBOM
    Write-Output "PASS: 21 SQL controls, all embedded/source hashes and exact replay ledger; retained $destination"
} finally { Pop-Location }
